@startuml

class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + Email : string
}

class Student extends Person {}

class School {
  + Name : string
}

class TeachingAssignment {
  + Hours : int
}

class ClassGroup {
  + Name : string
}

abstract class Room {
  + Name : string
}

class ClassRoom extends Room {
  + Capacity : int
}

class OtherRoom extends Room {
  + Size : double
}

School "1" -- "0..1" Teacher : "principal"
School "1" -- "1..*" Teacher : "employs"
School "1" -- "*" Student : "has"
Teacher "1..3" -- "*" School : "teaches"
Teacher "1" -- "*" TeachingAssignment : "performs"
School "1" -- "*" TeachingAssignment : "has"
Student "*" -- "1" ClassGroup : "belongs to"
ClassGroup "1" -- "1" ClassRoom : "assigned to"
School "1" *-- "*" Room : "consists of"

@enduml

